package com.bank.settlement.producer;

import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.apache.kafka.common.errors.NotEnoughReplicasException;
import lombok.extern.slf4j.Slf4j;
import java.math.BigDecimal;

@Slf4j
public class SettlementProducer {

    private final KafkaProducer<String, String> producer;

    public SettlementProducer(KafkaProducer<String, String> producer) {
        this.producer = producer;
    }

    public void publishSettlement(String accountId, BigDecimal amount) {
        try {
            // With min.insync.replicas=2, this send BLOCKS/FAILS if fewer than 2 replicas
            // are in-sync, so we never get a false "durable" acknowledgment.
            producer.send(new ProducerRecord<>("settlements", accountId,
                    "SETTLED " + amount.toPlainString())).get();
            log.info("Settlement durably stored on >=2 replicas for {}", accountId);
        } catch (Exception e) {
            if (e.getCause() instanceof NotEnoughReplicasException) {
                // Honest failure: durability floor not met, do NOT pretend success.
                log.error("Durability floor not met for {} — retry later, NOT acknowledged", accountId);
            } else {
                log.error("Settlement publish failed for {}", accountId, e);
            }
        }
    }
}
