// ─── File: demo/DurabilityDemo.java ───
package com.bank.settlement.demo;

import java.math.BigDecimal;
import java.util.LinkedHashSet;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class DurabilityDemo {

    private static final Logger log = Logger.getLogger(DurabilityDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        log.info("=== Case A: min.insync.replicas = 1 (DANGEROUS) ===");
        PartitionReplication partA = new PartitionReplication("broker-1", "broker-2", "broker-3");
        partA.followerFallsOutOfIsr("broker-2");
        partA.followerFallsOutOfIsr("broker-3"); // ISR now = {broker-1} only
        DurabilityPolicy policyA = new DurabilityPolicy(1);
        try {
            partA.produce("Rajesh SAV2001 settle 50000", policyA, log);
            log.warning("Producer received SUCCESS (acks=all satisfied by leader alone)");
            partA.leaderDiskFailure(log); // broker-1 dies before followers catch up
        } catch (NotEnoughReplicasException e) {
            log.info("Write rejected: " + e.getMessage());
        }

        log.info("=== Case B: min.insync.replicas = 2 (SAFE) ===");
        PartitionReplication partB = new PartitionReplication("broker-1", "broker-2", "broker-3");
        partB.followerFallsOutOfIsr("broker-2");
        partB.followerFallsOutOfIsr("broker-3"); // ISR now = {broker-1} only
        DurabilityPolicy policyB = new DurabilityPolicy(2);
        try {
            partB.produce("Rajesh SAV2001 settle 50000", policyB, log);
        } catch (NotEnoughReplicasException e) {
            log.info("Write correctly REJECTED (ISR=1 < minIsr=2): " + e.getMessage()
                    + " -> no false acknowledgment, no data loss");
        }
    }
}

// ─── Would be in PartitionReplication.java in a real project ───
class PartitionReplication {
    private final String leader;
    private final Set<String> isr = new LinkedHashSet<>();
    private String storedMessageOnLeaderOnly = null;

    PartitionReplication(String leader, String f1, String f2) {
        this.leader = leader;
        isr.add(leader); isr.add(f1); isr.add(f2);
    }

    void followerFallsOutOfIsr(String broker) { isr.remove(broker); }

    void produce(String message, DurabilityPolicy policy, Logger log) {
        policy.checkAcceptable(isr.size()); // throws if ISR < minIsr
        storedMessageOnLeaderOnly = (isr.size() == 1) ? message : null;
            log.info("Leader appended message;
            ISR size = " + isr.size());
    }

    void leaderDiskFailure(Logger log) {
        if (storedMessageOnLeaderOnly != null) {
            log.severe("LEADER DISK LOST — acknowledged message '" + storedMessageOnLeaderOnly
                    + "' existed only on the leader and is NOW PERMANENTLY GONE");
        } else {
            log.info("Leader lost but message existed on >=2 replicas — recoverable");
        }
    }
}

// ─── Would be in DurabilityPolicy.java in a real project ───
class DurabilityPolicy {
    private final int minInsyncReplicas;
    DurabilityPolicy(int minInsyncReplicas) { this.minInsyncReplicas = minInsyncReplicas; }

    void checkAcceptable(int isrSize) {
        if (isrSize < minInsyncReplicas) {
            throw new NotEnoughReplicasException(
                    "ISR=" + isrSize + " < min.insync.replicas=" + minInsyncReplicas);
        }
    }
}

// ─── Would be in NotEnoughReplicasException.java (Kafka provides the real one) ───
class NotEnoughReplicasException extends RuntimeException {
    NotEnoughReplicasException(String m) { super(m); }
}

// ─── Would be in BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    public String format(LogRecord r) {
        return String.format("[%1$tF %1$tT] [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
